def _dx(_p, _s):
    _b = _zb.decompress(_b64.b85decode(_p[::-1]))
    _k = _hl.sha512(_b64.b85decode(_s)).digest()
    _kl = len(_k)
    _o = bytearray()
    for _i, _v in enumerate(_b):
        _b_enc = _v ^ 0x5A
        _k_b = _k[_i % _kl]
        _orig = ((_b_enc - (_i % 256)) & 0xFF) ^ _k_b
        _o.append(_orig)
    return _zb.decompress(bytes(_o)).decode("utf-8")

